1	package com.example.starter.radio.repository;
2	
3	import java.sql.PreparedStatement;
4	import java.sql.Statement;
5	import java.util.List;
6	import java.util.Optional;
7	
8	import com.example.starter.radio.domain.ChangeOrderStatus;
9	import com.example.starter.radio.model.ChangeCheck;
10	import com.example.starter.radio.model.ChangeOrder;
11	import org.springframework.jdbc.core.JdbcTemplate;
12	import org.springframework.jdbc.support.GeneratedKeyHolder;
13	import org.springframework.jdbc.support.KeyHolder;
14	import org.springframework.stereotype.Repository;
15	
16	/**
17	 * 给药时刻变更候选单及其双人复核链数据访问。
18	 * 生效、作废与发药竞争均通过先锁分装行再锁候选行（FOR UPDATE）串行化。
19	 */
20	@Repository
21	public class ChangeOrderRepository {
22	
23	    private final JdbcTemplate jdbc;
24	
25	    public ChangeOrderRepository(JdbcTemplate jdbc) {
26	        this.jdbc = jdbc;
27	    }
28	
29	    public long insert(String requestId, String fingerprint, long dispensingId, int expectedVersion,
30	                       int prescriptionVersion, Long newPrescriptionId, long newAdministrationTimeEpoch,
31	                       int candidateVersionNo, Double candidateActivityBq, Double candidateDeviationRatio,
32	                       String calcStatus, ChangeOrderStatus status, long nowEpoch) {
33	        KeyHolder keys = new GeneratedKeyHolder();
34	        jdbc.update(con -> {
35	            PreparedStatement ps = con.prepareStatement(
36	                    "INSERT INTO dispensing_change_order (request_id, fingerprint, dispensing_id, expected_version,"
37	                            + " prescription_version, new_prescription_id, new_administration_time_epoch,"
38	                            + " candidate_version_no, candidate_activity_bq, candidate_deviation_ratio,"
39	                            + " calc_status, status, created_at_epoch, updated_at_epoch)"
40	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
41	                    Statement.RETURN_GENERATED_KEYS);
42	            ps.setString(1, requestId);
43	            ps.setString(2, fingerprint);
44	            ps.setLong(3, dispensingId);
45	            ps.setInt(4, expectedVersion);
46	            ps.setInt(5, prescriptionVersion);
47	            if (newPrescriptionId == null) {
48	                ps.setNull(6, java.sql.Types.BIGINT);
49	            } else {
50	                ps.setLong(6, newPrescriptionId);
51	            }
52	            ps.setLong(7, newAdministrationTimeEpoch);
53	            ps.setInt(8, candidateVersionNo);
54	            if (candidateActivityBq == null) {
55	                ps.setNull(9, java.sql.Types.DOUBLE);
56	            } else {
57	                ps.setDouble(9, candidateActivityBq);
58	            }
59	            if (candidateDeviationRatio == null) {
60	                ps.setNull(10, java.sql.Types.DOUBLE);
61	            } else {
62	                ps.setDouble(10, candidateDeviationRatio);
63	            }
64	            ps.setString(11, calcStatus);
65	            ps.setString(12, status.name());
66	            ps.setLong(13, nowEpoch);
67	            ps.setLong(14, nowEpoch);
68	            return ps;
69	        }, keys);
70	        return keys.getKey().longValue();
71	    }
72	
73	    public Optional<ChangeOrder> findById(long id) {
74	        return jdbc.query("SELECT * FROM dispensing_change_order WHERE id = ?",
75	                this::map, id).stream().findFirst();
76	    }
77	
78	    /**
79	     * 候选行锁；调用方须已持有对应分装行锁，统一锁顺序避免死锁。
80	     */
81	    public Optional<ChangeOrder> findByIdForUpdate(long id) {
82	        return jdbc.query("SELECT * FROM dispensing_change_order WHERE id = ? FOR UPDATE",
83	                this::map, id).stream().findFirst();
84	    }
85	
86	    public Optional<ChangeOrder> findBySubmitRequestId(String requestId) {
87	        return jdbc.query("SELECT * FROM dispensing_change_order WHERE request_id = ?",
88	                this::map, requestId).stream().findFirst();
89	    }
90	
91	    public Optional<ChangeOrder> findByVoidRequestId(String voidRequestId) {
92	        return jdbc.query("SELECT * FROM dispensing_change_order WHERE void_request_id = ?",
93	                this::map, voidRequestId).stream().findFirst();
94	    }
95	
96	    public Optional<ChangeOrder> findActiveByDispensingForUpdate(long dispensingId) {
97	        return jdbc.query(
98	                "SELECT * FROM dispensing_change_order WHERE dispensing_id = ? AND status = 'PENDING' FOR UPDATE",
99	                this::map, dispensingId).stream().findFirst();
100	    }
101	
102	    public List<ChangeOrder> findByDispensing(long dispensingId) {
103	        return jdbc.query(
104	                "SELECT * FROM dispensing_change_order WHERE dispensing_id = ? ORDER BY id",
105	                this::map, dispensingId);
106	    }
107	
108	    public int updateReviewer(long id, String reviewerColumn, String reviewer, long nowEpoch) {
109	        return jdbc.update("UPDATE dispensing_change_order SET " + reviewerColumn + " = ?, updated_at_epoch = ?"
110	                + " WHERE id = ?", reviewer, nowEpoch, id);
111	    }
112	
113	    /**
114	     * 双人复核通过、生效：记录第二复核人、新生效处方版本与生效时刻，候选置为 APPROVED。
115	     */
116	    public int markApproved(long id, String secondReviewer, long newPrescriptionId, long nowEpoch) {
117	        return jdbc.update(
118	                "UPDATE dispensing_change_order SET second_reviewer = ?, new_prescription_id = ?,"
119	                        + " status = 'APPROVED', approved_at_epoch = ?, updated_at_epoch = ? WHERE id = ?",
120	                secondReviewer, newPrescriptionId, nowEpoch, nowEpoch, id);
121	    }
122	
