 */
public enum DispensingStatus {

    /** 分装计算完成，待双人核对。 */
    CALCULATED,

    /** 两名不同人员先后核对完成，可发药。 */
    CHECKED,

    /** 发药完成，终态；重复完成返回幂等成功。 */
    DISPENSED,

    /** 分装活度与处方偏差超过 ±10%，已拒绝，终态。 */
    REJECTED,

    /** 未发药整批撤回批准后作废，终态；原计算与签认保留为证据，不得重新激活、发药、改时刻或重新核对。 */
    VOID
}

