    int withdrawWins = 0;
    int changeWins = 0;
    for (int run = 0; run < 5; run++) {
        // 已双人核对的合法分装，同时挂一张待复核时刻候选（已完成第一复核）和一张待批准撤回单（已完成第一批准）
